sp_widget.client_script:
api.controller = function($scope) { 
    $scope.goToSubmitFeedback = function() { 
        var recordProducerSysId = '5b76eaebc3cb6210319033fc050131cb'; 
        var url = '/sp?id=record_producer&sys_id=' + recordProducerSysId; 
        window.location.href = url; 
    }; 
};

sp_widget.css:
.custom-action-card-feedback {
    background: linear-gradient(135deg, #ffe0b2, #fff3e0);
    border-radius: 20px;
    padding: 30px 20px;
    box-shadow: 0 8px 20px rgba(255, 152, 0, 0.1);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.custom-action-card-feedback:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 25px rgba(255, 152, 0, 0.2);
}

.icon-wrapper-feedback {
    background: #fb8c00;
    color: white;
    width: 80px;
    height: 80px;
    margin: 0 auto 20px auto;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    box-shadow: 0 4px 10px rgba(251, 140, 0, 0.4);
}

.custom-action-card-feedback h4 {
    margin-bottom: 20px;
    font-weight: bold;
    color: #ef6c00;
}

.action-btn-feedback {
    background: #f57c00;
    color: white;
    padding: 12px 20px;
    font-size: 16px;
    border: none;
    border-radius: 10px;
    width: 100%;
    transition: background 0.3s ease;
}

.action-btn-feedback:hover {
    background: #ef6c00;
    color: #fff;
}
